export function failExistingSpinner() {
  spinner?.fail();
  spinner = null;
}

export function logFailure(message: string) {
  if (spinner) {
    spinner.fail(message);
    spinner = null;
  } else {
    logToStderr(`${chalkStderr.red(`✖`)} ${message}`);
  }
