export async function subscribe(
  ctx: Context,
  args: {
    deploymentUrl: string;
    adminKey: string;
    identity?: UserIdentityAttributes | undefined;
    parsedFunctionName: string;
    parsedFunctionArgs: Record<string, Value>;
    componentPath: string | undefined;
    until: Promise<unknown>;
    callbacks?:
      | {
          onStart?: () => void;
          onChange?: (result: Value) => void;
          onStop?: () => void;
        }
      | undefined;
  },
) {
  const client = new BaseConvexClient(
    args.deploymentUrl,
    (updatedQueries) => {
      for (const queryToken of updatedQueries) {
        let result: Value;
        try {
          result = client.localQueryResultByToken(queryToken)!;
        } catch (err) {
          // A failed query (e.g. a permission error) throws here. Surface
          // permission errors cleanly instead of an uncaught stack trace, and
          // let any other error propagate as before.
          const permissionError = permissionDeniedErrorMessage(
            (err as Error).toString(),
          );
          if (permissionError !== null) {
            void ctx.crash({
              exitCode: 1,
              errorType: "fatal",
              printedMessage: chalkStderr.red(permissionError),
