type LocalQuery = {
  id: QueryId;
  canonicalizedUdfPath: string;
  args: Record<string, Value>;
  numSubscribers: number;
  journal?: QueryJournal | undefined;
  componentPath?: string | undefined;
};

export type AuthState =
