    await typeCheckFunctions(
      ctx,
      typescriptCompiler,
      functionsDir,
      async (result, logSpecificError, runOnError) => {
        if (
          (result === "cantTypeCheck" && typeCheckMode === "enable") ||
          result === "typecheckFailed"
