async function selectEnvDeployment(
  options: DeploymentSelectionOptions,
): Promise<{
  ctx: Context;
  deployment: {
    deploymentUrl: string;
    deploymentName: string;
    deploymentType: "dev" | "preview" | "prod";
    adminKey: string;
    deploymentNotice: string;
  };
}> {
