  logFinishedStep(
    `Created project ${chalkStderr.bold(projectSlug)} in team ` +
      `${chalkStderr.bold(team.slug)}, manage it at ${chalkStderr.bold(
        projectDashboardUrl(team.slug, projectSlug),
