  );
  logMessage(
    chalkStderr.gray(
      `Next, add a deployment with ` +
        `\`npx convex deployment create ${team.slug}:${projectSlug}:dev --type dev\` ` +
        `(pass \`--region us\` to choose a region).`,
    ),
  );
}

