  if (inlineQuery !== undefined && args.functionName !== undefined) {
    return await args.ctx.crash({
      exitCode: 1,
      errorType: "fatal",
      printedMessage:
        "`npx convex run` accepts either <functionName> or `--inline-query`, not both.",
    });
