  if (inlineQuery === undefined) {
    if (args.functionName === undefined) {
      return await args.ctx.crash({
        exitCode: 1,
        errorType: "fatal",
        printedMessage:
          "`npx convex run` requires either <functionName> or `--inline-query`.",
      });
    }
