  return await args.ctx.crash({
    exitCode: 1,
    errorType: "fatal",
    printedMessage:
      `Component path "${componentPath}" was not found.\n\n` +
      `${availableComponentsMessage}\n` +
      "Omit `--component` to target the app root.",
  });
}
